function route({ ticket, ticketId, fieldId, comment }) {
  if (ticket?.id !== ticketId || !Array.isArray(ticket?.raw?.custom_fields))
    throw Error("Ticket ID or custom fields invalid");
  const matches = ticket.raw.custom_fields.filter((x) => x?.id === fieldId);
  if (matches.length !== 1) throw Error("Configured Jira issue field is absent or duplicated");
  const value = matches[0].value;
  if (value == null || value === "") {
    if (typeof ticket.subject !== "string" || !ticket.subject.trim())
      throw Error("Ticket subject is missing");
    const url =
      typeof ticket.raw.url === "string"
        ? ticket.raw.url.match(
            /^https:\/\/([a-z0-9-]+\.zendesk\.com)\/api\/v2\/tickets\/(\d+)\.json$/i,
          )
        : null;
    if (!url || url[2] !== String(ticketId)) throw Error("Invalid Zendesk ticket URL");
    return {
      existing: false,
      key: "-",
      title: ticket.subject.trim(),
      description: `See Zendesk issue at: https://${url[1]}/agent/tickets/${ticketId}`,
      comment: "-",
    };
  }
  if (typeof value !== "string" || !value.trim() || value !== value.trim())
    throw Error("Invalid stored Jira issue key");
  if (!comment.trim()) throw Error("A comment is required for an existing issue");
  return { existing: true, key: value, title: ticket.subject || "-", description: "-", comment };
}

const r = $("Validate the ticket event").first().json;
return {
  json: route({
    ticket: { id: $json.id, subject: $json.subject, raw: $json },
    ticketId: r.ticketId,
    fieldId: r.fieldId,
    comment: r.comment,
  }),
};

function request({ body, secret, fieldId, projectId, issueTypeId }) {
  if (typeof secret !== "string" || secret.length < 24 || body?.secret !== secret)
    throw Error("Invalid webhook secret");
  const rawId = body?.id;
  if (!((typeof rawId === "string" && /^\d+$/.test(rawId)) || typeof rawId === "number"))
    throw Error("Invalid ticket ID");
  const ticketId = Number(rawId);
  if (!Number.isSafeInteger(ticketId) || ticketId < 1) throw Error("Invalid ticket ID");
  if (
    !Number.isSafeInteger(fieldId) ||
    fieldId < 1 ||
    !projectId ||
    projectId === "YOUR_PROJECT_ID" ||
    !issueTypeId ||
    issueTypeId === "YOUR_ISSUE_TYPE_ID"
  )
    throw Error("Configure the custom field, Jira project and issue type");
  const comment = body?.comment;
  if (comment != null && typeof comment !== "string") throw Error("Invalid comment");
  return { ticketId, comment: comment ?? "", fieldId, projectId, issueTypeId };
}

return {
  json: request({
    body: $json.body,
    secret: $env.ZENDESK_JIRA_SECRET,
    fieldId: 0,
    projectId: "YOUR_PROJECT_ID",
    issueTypeId: "YOUR_ISSUE_TYPE_ID",
  }),
};
